import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        details TEXT,
        ts DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports partial matching."""
    query_param = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Validate field against allowed columns
    allowed_fields = ['username', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query - field is validated above so safe to interpolate
    # But query_param is user-controlled and directly interpolated
    sql = f"SELECT id, username, role FROM users WHERE {field} LIKE '%{query_param}%'"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(password.encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    try:
        db = get_db()
        db.execute(
            'INSERT INTO users (username, password_hash, api_key) VALUES (?, ?, ?)',
            (username, password_hash, api_key)
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Export all user data for backup. Requires admin API key."""
    api_key = request.headers.get('X-API-Key', '')
    db = get_db()
    admin = db.execute(
        'SELECT * FROM users WHERE api_key = ? AND role = ?',
        (api_key, 'admin')
    ).fetchone()

    if not admin:
        return jsonify({'error': 'Unauthorized'}), 403

    users = db.execute('SELECT id, username, role, api_key FROM users').fetchall()
    return jsonify([dict(u) for u in users])

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
